INSERT INTO "data_sources" ("source_key", "name", "purpose", "access_level", "reference_only", "access_status", "metadata_json", "active") VALUES
  ('boreholes_database', 'Supplied borehole inventory', 'Local user-supplied national borehole inventory for authorized record import. Historical depth, static water level and yield attributes are present; coordinates remain unverified because the source datum is unknown.', 'restricted', false, 'Available locally · 17,232 supplied borehole features · coordinate datum unknown; records remain unverified.', '{"provider":"User-supplied borehole inventory","localFile":"data/geospatial/borehole_database-1758978934.geojson","featureCount":17232,"portal":"https://sadc-gip.quartex.co.za/","sourceMetadata":"geod_datum is UNKNOWN","verificationStatus":"unverified","status":"available_local"}', true),
  ('main_catchments', 'Main catchments', 'Seven national catchment polygons for geographic reference and routing only; not a screening or compliance decision layer.', 'authenticated', true, 'Available locally · 7 catchment polygons · reference only; confirm CRS before measurement.', '{"provider":"Zimbabwe Geoportal dataset; user-supplied local file","localFile":"data/geospatial/catchments-1761164005/catchments-1761164004.geojson","featureCount":7,"portal":"https://stagging.zimgeoportal.org.zw/datasets/main-catchments/","license":"PDDL 1.0 (Geoportal metadata)","coordinateReferenceSystem":"CRS84 declared by GeoJSON; associated QGIS sidecar reports EPSG:32735","verificationStatus":"reference_only","decisionUse":false,"status":"available_local"}', true),
  ('regional_hydrogeological_map', 'Zimbabwe regional hydrogeology', 'Historical hydrogeology reference context; not a contamination layer, water-quality observation or decision rule.', 'public', true, 'Available locally · 2,315 hydrogeology polygons · reference only; approximate WGS 84 display conversion.', '{"provider":"IGRAC / SADC-GIP","sourceTitle":"Georeferencing and digitizing the national hydrogeological map of Zimbabwe - GeoPackage file","localFile":"/datasets/zimbabwe-hydrogeology-reference.geojson","featureCount":2315,"sourceMapDate":"1986","digitizedDate":"2022-12-20","license":"CC BY-SA 4.0","portal":"https://sadc-gip.org:4443/catalogue/#/document/496","coordinateReferenceSystem":"WGS 84 display conversion from source GeoPackage with unspecified datum; visual context only","verificationStatus":"reference_only","decisionUse":false,"status":"available_local"}', true),
  ('groundwater_inventory', 'Groundwater level and yield observations', 'Historical values from the supplied national borehole inventory. Includes static water level and borehole yield observations; it is not a current monitoring feed, and supplied chemistry fields contain no measurements.', 'restricted', true, 'Available locally · 9,436 static water-level values · 9,740 yield values · historical borehole records; no chemistry values in supplied file.', '{"provider":"User-supplied national borehole inventory","localFile":"data/geospatial/borehole_database-1758978934.geojson","sourceKey":"boreholes_database","featureCount":17232,"reportedValueCounts":{"staticWaterLevelM":9436,"yieldLitresPerSecond":9740,"electricalConductivity":0,"totalDissolvedSolids":0,"fluoride":0,"nitrate":0},"completionYearRange":[1938,2002],"coordinateDatum":"UNKNOWN","portal":"https://sadc-gip.quartex.co.za/","verificationStatus":"historical_unverified","status":"available_local"}', true),
  ('sadc_groundwater_portal', 'SADC Groundwater Information Portal', 'External portal for regional hydrogeology, borehole information and selected groundwater quality attributes where reported. Coverage and download permissions are governed by the portal.', 'authenticated', true, 'Available online · browse SADC groundwater maps and associated borehole data; Zimbabwe parameter coverage varies by dataset.', '{"provider":"SADC Groundwater Management Institute / IGRAC","portal":"https://sadc-gip.quartex.co.za/","providerInformation":"https://un-igrac.org/our-work/activities/sadc-groundwater-information-portal-gip/","content":"Harmonized hydrogeological maps, borehole data and associated information; selected chemical parameters may be available","verificationStatus":"external_reference","decisionUse":false,"status":"available_online"}', true),
  ('zinwa_dam_levels', 'ZINWA dam levels and catchment summaries', 'Official external surface-water dashboard with dam storage and catchment summaries. Figures can change between snapshots and are not groundwater-quality measurements.', 'public', true, 'Available online · official ZINWA dam-level dashboard and catchment summaries.', '{"provider":"Zimbabwe National Water Authority","portal":"https://zinwa.co.zw/dam-levels/","providerInformation":"https://zinwa.co.zw/fees-charges/","dataType":"surface_water_dam_storage","verificationStatus":"external_reference","decisionUse":false,"status":"available_online"}', true)
